rtl:
always_ff @(posedge clk)
  case (state)  // 3-bit state, only 0-4 handled — no default
    3'h0: state <= 3'h1;
    3'h1: state <= 3'h2;
    3'h2: state <= 3'h3;
    3'h3: state <= 3'h4;
    3'h4: state <= 3'h0;
  endcase

fix_replacement:
always_ff @(posedge clk or negedge rst_n)
  if (!rst_n) state <= 3'h0;
  else case (state)
    3'h0: state <= 3'h1;
    3'h1: state <= 3'h2;
    3'h2: state <= 3'h3;
    3'h3: state <= 3'h4;
    3'h4: state <= 3'h0;
    default: state <= 3'h0;  // Escape illegal states
  endcase
